extends SceneTree
func _initialize():
    var input = JSON.parse_string(OS.read_string_from_stdin())
    if not input is Dictionary:
        printerr("Input must be an object")
        quit(1)
        return
    var count = clampi(int(input.get("count", 8)), 1, 100)
    var root = Node3D.new()
    root.name = "GeneratedLevel"
    for i in range(count):
        var tile = MeshInstance3D.new()
        tile.name = "Platform" + str(i)
        tile.mesh = BoxMesh.new()
        tile.position = Vector3(i * 2.0, 0, (i % 3) * 2.0)
        root.add_child(tile)
        tile.owner = root
    var packed = PackedScene.new()
    if packed.pack(root) != OK or ResourceSaver.save(packed, "res://generated.tscn") != OK:
        root.free()
        quit(1)
        return
    var output = {"scene_text":FileAccess.get_file_as_string("res://generated.tscn"),"platforms":count,"blocks":[{"kind":"heading","level":1,"text":"Generated Godot scene"},{"kind":"paragraph","text":str(count)+" platform meshes packed into generated.tscn. Connect scene_text through a process to a Write file node to save it into your own project."}]}
    print("CONSILIUM_RESULT:" + JSON.stringify(output))
    root.free()
    quit()
